package com.quincaisoft.returns.application;
import com.quincaisoft.returns.api.ReturnService;import com.quincaisoft.returns.infrastructure.*;import com.quincaisoft.sales.api.SalesService;import com.quincaisoft.finance.api.FinanceService;import com.quincaisoft.inventory.api.StockService;import com.quincaisoft.catalog.api.CatalogService;import com.quincaisoft.documents.api.DocumentService;import com.quincaisoft.shared.*;
import jakarta.persistence.*;import org.springframework.stereotype.Service;import tools.jackson.databind.json.JsonMapper;import java.util.*;import java.time.*;import java.math.BigInteger;import java.security.*;import java.nio.charset.StandardCharsets;import java.util.function.Supplier;
@Service public class DefaultReturnService implements ReturnService {
 private final EntityManager em;private final ScopedTransactions tx;private final SalesService sales;private final FinanceService finance;private final StockService stock;private final CatalogService catalog;private final DocumentService documents;private final JsonMapper json;
 public DefaultReturnService(EntityManager em,ScopedTransactions tx,SalesService sales,FinanceService finance,StockService stock,CatalogService catalog,DocumentService documents,JsonMapper json){this.em=em;this.tx=tx;this.sales=sales;this.finance=finance;this.stock=stock;this.catalog=catalog;this.documents=documents;this.json=json;}
 private CustomerReturnEntity row(UUID id,boolean lock){var s=TenantContext.current();var r=em.find(CustomerReturnEntity.class,new CustomerReturnEntity.Key(s.tenantId(),s.companyId(),id),lock?LockModeType.PESSIMISTIC_WRITE:LockModeType.NONE);if(r==null)throw new NoSuchElementException("Return not found");return r;}
 private List<CustomerReturnLine> lines(UUID id){return em.createQuery("select l from CustomerReturnLine l where l.returnId=:id order by l.id",CustomerReturnLine.class).setParameter("id",id).getResultList();}
 private CustomerReturn view(CustomerReturnEntity r){return new CustomerReturn(r.id,r.saleId,r.status,r.businessDate,r.version,r.evidenceReference,Long.toString(r.creditXaf),Long.toString(r.customerCreditXaf),lines(r.id).stream().map(l->new Line(l.productId,Long.toString(l.quantityMilli),Long.toString(l.creditXaf))).toList());}
 public CustomerReturn get(UUID id){return tx.execute(()->view(row(id,false)));}
 public List<CustomerReturn> list(){return tx.execute(()->em.createQuery("select r from CustomerReturnEntity r order by r.createdAt desc,r.id",CustomerReturnEntity.class).setMaxResults(100).getResultList().stream().map(this::view).toList());}
 public CustomerReturn draft(Draft d){if(d==null||d.operationId()==null||d.saleId()==null||d.businessDate()==null||!"SELLABLE".equals(d.condition())||d.evidenceReference()==null||d.evidenceReference().isBlank()||d.lines()==null||d.lines().isEmpty()||d.lines().size()>500)throw new IllegalArgumentException("Sale, date, sellable inspection evidence and lines required");return tx.execute(()->once(d.operationId(),"DRAFT|"+d,()->{var sale=sales.valuation(d.saleId());if(d.businessDate().isBefore(sale.businessDate()))throw new IllegalArgumentException("Return precedes sale");var s=TenantContext.current();var r=new CustomerReturnEntity();r.id=UUID.randomUUID();r.tenantId=s.tenantId();r.companyId=s.companyId();r.branchId=s.branchId();r.createdBy=s.actorId();r.saleId=d.saleId();r.warehouseId=sale.warehouseId();r.customerId=sale.customerId();r.operationId=d.operationId();r.businessDate=d.businessDate();r.conditionCode=d.condition();r.evidenceReference=d.evidenceReference();r.status="DRAFT";r.createdAt=Instant.now();em.persist(r);em.flush();var seen=new HashSet<UUID>();for(var input:d.lines()){if(input==null||input.productId()==null||!seen.add(input.productId())||input.quantityMilli()==null||!input.quantityMilli().matches("[1-9][0-9]*"))throw new IllegalArgumentException("Distinct positive return quantities required");var source=sale.lines().stream().filter(l->l.productId().equals(input.productId())).findFirst().orElseThrow(()->new IllegalArgumentException("Product absent from original sale"));long q=Long.parseLong(input.quantityMilli());if(q>source.quantityMilli())throw new IllegalArgumentException("Return exceeds source quantity");var l=new CustomerReturnLine();l.tenantId=r.tenantId;l.companyId=r.companyId;l.id=UUID.randomUUID();l.returnId=r.id;l.productId=input.productId();l.quantityMilli=q;l.creditXaf=proportion(source.revenueXaf(),q,source.quantityMilli());l.costXaf=proportion(source.costXaf(),q,source.quantityMilli());r.creditXaf=Math.addExact(r.creditXaf,l.creditXaf);em.persist(l);}em.flush();return r;}));}
 public static long proportion(long value,long part,long whole){var qr=BigInteger.valueOf(value).multiply(BigInteger.valueOf(part)).divideAndRemainder(BigInteger.valueOf(whole));if(qr[1].signum()!=0)throw new IllegalArgumentException("Partial credit requires approved FCFA rounding policy");return qr[0].longValueExact();}
 private void valid(CustomerReturnEntity r,Command c,String status){if(c.operationId()==null||c.reason()==null||c.reason().isBlank())throw new IllegalArgumentException("Operation and reason required");if(r.version!=c.version())throw new RevisionConflict("Return changed");if(!status.equals(r.status))throw new IllegalStateException("Return must be "+status);}
 public CustomerReturn approve(UUID id,Command c){return tx.execute(()->once(c.operationId(),"APPROVE|"+id+"|"+c,()->{var r=row(id,true);valid(r,c,"DRAFT");finance.requireOpenPeriod(r.businessDate);if(r.createdBy.equals(TenantContext.current().actorId()))throw new IllegalStateException("A different operator must approve the return");r.approvedBy=TenantContext.current().actorId();r.status="APPROVED";r.version++;em.flush();return r;}));}
 public CustomerReturn post(UUID id,Command c){return tx.execute(()->once(c.operationId(),"POST|"+id+"|"+c,()->{var r=row(id,true);valid(r,c,"APPROVED");var s=TenantContext.current();em.createNativeQuery("select 1 from pg_advisory_xact_lock(hashtextextended(:k,0))").setParameter("k","return:"+s.tenantId()+r.saleId).getSingleResult();var sale=sales.valuation(r.saleId);long cost=0;var items=lines(id);for(var l:items){var source=sale.lines().stream().filter(x->x.productId().equals(l.productId)).findFirst().orElseThrow();var prior=em.createQuery("select coalesce(sum(l.quantityMilli),0) from CustomerReturnLine l,CustomerReturnEntity r where l.returnId=r.id and r.saleId=:sale and r.status='POSTED' and l.productId=:p",Long.class).setParameter("sale",r.saleId).setParameter("p",l.productId).getSingleResult();if(Math.addExact(prior,l.quantityMilli)>source.quantityMilli())throw new IllegalStateException("Return exceeds remaining eligible sale quantity");stock.receive(r.warehouseId,l.productId,l.quantityMilli,l.costXaf,UUID.nameUUIDFromBytes((c.operationId()+":"+l.id).getBytes(StandardCharsets.UTF_8)),c.reason());cost=Math.addExact(cost,l.costXaf);}
 var split=finance.applyCredit(r.saleId,r.creditXaf);var entries=new ArrayList<FinanceService.Entry>();entries.add(new FinanceService.Entry("SALES_RETURNS",r.creditXaf,0));if(split.appliedToReceivable()>0)entries.add(new FinanceService.Entry("ACCOUNTS_RECEIVABLE",0,split.appliedToReceivable()));if(split.customerCredit()>0)entries.add(new FinanceService.Entry("CUSTOMER_CREDITS",0,split.customerCredit()));entries.add(new FinanceService.Entry("MERCHANT_INVENTORY",cost,0));entries.add(new FinanceService.Entry("COST_OF_GOODS_SOLD",0,cost));finance.post(r.id,c.operationId(),r.businessDate,"CUSTOMER_RETURN",entries);r.customerCreditXaf=split.customerCredit();
 documents.issue(new DocumentService.Issue(r.id,c.operationId(),"CREDIT_NOTE",r.businessDate,r.customerId,Long.toString(r.creditXaf),items.stream().map(l->{var p=catalog.get(l.productId);return new DocumentService.Item(l.productId,p.sku(),p.name(),p.baseUnit(),Long.toString(l.quantityMilli),"0",Long.toString(l.creditXaf));}).toList(),r.saleId));r.status="POSTED";r.version++;em.flush();em.createNativeQuery("insert into outbox_event(tenant_id,id,company_id,branch_id,operation_id,event_type,aggregate_type,aggregate_id,payload) values(:t,:id,:c,:b,:o,'CustomerReturnPosted.v1','customer_return',:r,cast(:p as jsonb))").setParameter("t",r.tenantId).setParameter("id",UUID.randomUUID()).setParameter("c",r.companyId).setParameter("b",r.branchId).setParameter("o",c.operationId()).setParameter("r",r.id).setParameter("p",json.writeValueAsString(view(r))).executeUpdate();return r;}));}
 private CustomerReturn once(UUID op,String material,Supplier<CustomerReturnEntity> work){if(op==null)throw new IllegalArgumentException("Operation required");var s=TenantContext.current();String hash;try{hash=HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(material.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}em.createNativeQuery("select 1 from pg_advisory_xact_lock(hashtextextended(:k,0))").setParameter("k",s.tenantId()+":"+op).getSingleResult();var prior=em.createNativeQuery("select request_hash,source_type,response_json::text from idempotency_result where tenant_id=:t and operation_id=:o").setParameter("t",s.tenantId()).setParameter("o",op).getResultList();if(!prior.isEmpty()){Object[] old=(Object[])prior.getFirst();if(!hash.equals(old[0])||!"RETURN".equals(old[1]))throw new IllegalStateException("Operation ID reused");if(old[2]==null)throw new IllegalStateException("Committed operation response expired");return json.readValue((String)old[2],CustomerReturn.class);}var r=work.get();var out=view(r);em.createNativeQuery("insert into idempotency_result(tenant_id,operation_id,company_id,branch_id,request_hash,source_type,source_id,response_json) values(:t,:o,:c,:b,:h,'RETURN',:s,cast(:r as jsonb))").setParameter("t",s.tenantId()).setParameter("o",op).setParameter("c",s.companyId()).setParameter("b",s.branchId()).setParameter("h",hash).setParameter("s",r.id).setParameter("r",json.writeValueAsString(out)).executeUpdate();return out;}
}